import sys

def is_arithmetic(seq):
    if len(seq) < 2:
        return True
    d = seq[1] - seq[0]
    return all(seq[i] - seq[i-1] == d for i in range(2, len(seq)))

def main():
    import sys
    import itertools
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))

    for i in range(1, n):
        for combination in itertools.combinations(range(n), i):
            progression1 = [a[j] for j in combination]
            progression2 = [a[j] for j in range(n) if j not in combination]
            if is_arithmetic(sorted(progression1)) and is_arithmetic(sorted(progression2)):
                print(' '.join(map(str, sorted(progression1))))
                print(' '.join(map(str, sorted(progression2))))
                return
    print("No solution")

main()
